// Brush training in the browser (`brush-js` bindings, generated by `pnpm web:wasm`).

import init, { BrushApp, BrushMessageKind, type BrushMessage, type Training } from "../pkg/brush_js.js";
import type { Msg, TrainOptions } from "../../src/lib/api";
import { trainConfig } from "./pipeline/train-config";

export interface GpuInfo {
  vendor: string;
  architecture: string;
  description: string;
  subgroups: boolean;
  maxBufferSize: number;
  maxStorageBinding: number;
}

let runtime: Promise<{ app: BrushApp; gpu: GpuInfo; device: GPUDevice }> | null = null;

/** Boots the WASM and a GPUDevice with the adapter's max limits (Brush needs
 *  `subgroups` and large buffers). Once per page. */
export function brushRuntime() {
  runtime ??= (async () => {
    if (!("gpu" in navigator)) throw new Error("This browser does not support WebGPU.");
    const adapter = await navigator.gpu.requestAdapter({ powerPreference: "high-performance" });
    if (!adapter) throw new Error("No WebGPU adapter available.");
    // `mappable-primary-buffers` shows up on some Chrome adapters but is
    // rejected by requestDevice.
    const features = [...adapter.features].filter((f) => f !== "mappable-primary-buffers") as GPUFeatureName[];
    const requiredLimits: Record<string, number> = {};
    for (const k in adapter.limits) {
      const v = (adapter.limits as unknown as Record<string, number>)[k];
      if (typeof v === "number") requiredLimits[k] = v;
    }
    const device = await adapter.requestDevice({ requiredFeatures: features, requiredLimits });
    if (device.features.has("subgroups")) enableSubgroupsInShaders(device);
    await init();
    const app = new BrushApp();
    app.initExisting(adapter, device, device.queue);
    const info = adapter.info;
    return {
      app,
      device,
      gpu: {
        vendor: info.vendor,
        architecture: info.architecture,
        description: info.description,
        subgroups: adapter.features.has("subgroups"),
        maxBufferSize: device.limits.maxBufferSize,
        maxStorageBinding: device.limits.maxStorageBufferBindingSize,
      },
    };
  })();
  runtime.catch(() => (runtime = null));
  return runtime;
}

const SUBGROUP_USE = /\bsubgroup[A-Z]\w*\s*\(|@builtin\(\s*subgroup_/;

/** naga's WGSL writer (wgpu 30) uses subgroup functions without emitting
 *  `enable subgroups;`, which Chrome requires since the extension left
 *  experimental: without it Brush's sort/scan kernels don't compile. wgpu calls
 *  `device.createShaderModule` through the JS object, so overriding the method
 *  on this instance is enough. */
function enableSubgroupsInShaders(device: GPUDevice) {
  const create = device.createShaderModule.bind(device);
  device.createShaderModule = (desc) =>
    create(
      SUBGROUP_USE.test(desc.code) && !/^\s*enable\s+subgroups\s*;/m.test(desc.code)
        ? { ...desc, code: `enable subgroups;\n${desc.code}` }
        : desc,
    );
}

/** `initial` with the run's options (see trainConfig) and `extra` on top;
 *  keys this Brush build doesn't have are logged and skipped. */
function applyOptions(
  cfg: Record<string, unknown>,
  o: TrainOptions,
  masked: boolean,
  log: (s: string) => void,
  extra: Record<string, unknown> = {},
) {
  const set = { ...trainConfig(o, masked), ...extra };
  for (const [k, v] of Object.entries(set)) {
    if (k in cfg) cfg[k] = v;
    else log(`Option "${k}" does not exist in this Brush version; ignored.`);
  }
  return cfg;
}

// Steps per call into WASM: more amortizes the JS↔WASM boundary; fewer keeps
// cancellation and the progress bar more responsive.
const STEPS_PER_BATCH = 10;

export interface TrainEvents {
  status(msg: Msg): void;
  dataset(train: number, evalViews: number): void;
  /** Once per batch of steps. */
  step(iter: number, splats: number): void;
  eval(iter: number, psnr: number, ssim: number): void;
  /** Preview every `exportEvery` steps (training waits for the GPU readback). */
  snapshot(iter: number, ply: Uint8Array): void;
  log(line: string): void;
}

/** Extra knobs for special runs (mesh fine-tune). */
export interface TrainExtras {
  /** Brush config keys (kebab-case) set on top of `opts`. */
  config?: Record<string, unknown>;
  /** Runs after the last step, while the run's splats are still alive (e.g. to
   *  render from them); the run is freed afterwards. */
  finish?: (t: Training) => Promise<void>;
}

/** Trains the folder's dataset and returns the final .ply. `masked`: the images
 *  carry the mask alpha (dataset_alpha). Dropping the stream (on cancel)
 *  discards Burn's pending work. */
export async function train(
  dir: FileSystemDirectoryHandle,
  opts: TrainOptions,
  masked: boolean,
  ev: TrainEvents,
  signal: AbortSignal,
  extras: TrainExtras = {},
): Promise<Uint8Array> {
  const { app } = await brushRuntime();
  const t = app.startTrainingFromDirectory(dir, async (initial: Record<string, unknown>) =>
    applyOptions({ ...initial }, opts, masked, ev.log, extras.config),
  );
  let iter = 0, splats = 0, lastSnapshot = 0;
  const handle = (m: BrushMessage) => {
    switch (m.kind) {
      case BrushMessageKind.StartLoading:
        ev.status(m.name ? { key: "train.loadingNamed", args: { name: m.name } } : { key: "train.loading" });
        break;
      case BrushMessageKind.DatasetLoaded:
        ev.dataset(m.trainViews ?? 0, m.evalViews ?? 0);
        break;
      case BrushMessageKind.SplatsUpdated:
      case BrushMessageKind.RefineStep:
        if (m.numSplats != null) splats = m.numSplats;
        if (m.prunedHarmful) ev.log(`step ${m.iter}: ${m.prunedHarmful} Gaussians pruned for negative contribution`);
        break;
      case BrushMessageKind.TrainStep:
        iter = m.iter ?? iter;
        break;
      case BrushMessageKind.EvalResult:
        ev.eval(m.iter ?? iter, m.psnr ?? 0, m.ssim ?? 0);
        break;
      case BrushMessageKind.Warning:
        ev.log(`warning: ${m.text ?? ""}`);
        break;
    }
    m.free();
  };
  try {
    for (;;) {
      if (signal.aborted) throw new DOMException("cancelled", "AbortError");
      const msgs = await t.trainSteps(STEPS_PER_BATCH);
      if (msgs.length === 0) break;
      const before = iter;
      for (const m of msgs) handle(m);
      if (iter > before) ev.step(iter, splats);
      if (opts.exportEvery > 0 && iter - lastSnapshot >= opts.exportEvery && iter < opts.totalSteps) {
        lastSnapshot = iter;
        const ply = await t.exportPly();
        if (ply) ev.snapshot(iter, ply);
      }
    }
    if (signal.aborted) throw new DOMException("cancelled", "AbortError");
    const ply = await t.exportPly();
    if (!ply) throw new Error("Brush did not return the final splat");
    if (extras.finish) await extras.finish(t);
    return ply;
  } finally {
    t.free();
  }
}
